from __future__ import annotations

from dataclasses import dataclass
from itertools import combinations
from typing import Generic, Iterable, List, Sequence, TypeVar

from relationing.structure.exclusion_atoms import ExclusionAtom, atoms_from_relationlessness
from relationing.structure.heyting_algebra import HeytingAlgebra
from relationing.structure.relationlessness import Relationlessness


A = TypeVar("A", bound=HeytingAlgebra)


@dataclass(frozen=True)
class FiniteHeytingAlgebra(Generic[A]):
    """Finite Heyting subalgebra generated by a seed.

    Given a finite collection of recognitions in some Heyting algebra
    (for example, elements of a powerset algebra over an
    exclusion-derived universe), the closure under ∧, ∨, ⇒ again forms
    a finite Heyting algebra. This value object simply records the
    resulting finite carrier.
    """

    elements: tuple[A, ...]

    def as_list(self) -> list[A]:
        """Return the carrier elements as a list."""

        return list(self.elements)


def close_under_heyting_ops(seed: Iterable[A]) -> FiniteHeytingAlgebra[A]:
    """Generate the finite Heyting subalgebra closed under ∧, ∨, ⇒.

    Starting from a finite "seed" of recognitions, repeatedly apply
    meet, join, and implication until a fixed point is reached. The
    result is a finite Heyting algebra whose carrier consists of all
    elements reachable from the seed via those operations.

    This is intended for small, concrete models (for example,
    subalgebras inside the exclusion-derived powerset carriers); it is
    not optimised for large universes.
    """

    carrier: List[A] = []
    for x in seed:
        if x not in carrier:
            carrier.append(x)

    changed = True
    while changed:
        changed = False
        current: Sequence[A] = tuple(carrier)
        for a in current:
            for b in current:
                for x in (a.meet(b), a.join(b), a.imp(b)):
                    if x not in carrier:
                        carrier.append(x)
                        changed = True

    return FiniteHeytingAlgebra(elements=tuple(carrier))


@dataclass(frozen=True)
class PowersetHeytingElement(HeytingAlgebra):
    """Element of a finite powerset Heyting algebra over exclusion atoms.

    The underlying carrier is a finite set of exclusion atoms arising
    from Relationlessness. Each element is a subset of that universe,
    with the Heyting structure given by the standard powerset Boolean
    algebra operations.
    """

    universe: frozenset[ExclusionAtom]
    subset: frozenset[ExclusionAtom]

    def leq(self, other: "PowersetHeytingElement") -> bool:
        if self.universe != other.universe:
            raise ValueError("cannot compare elements from different universes")
        return self.subset.issubset(other.subset)

    @classmethod
    def bottom(cls) -> "PowersetHeytingElement":  # type: ignore[override]
        """Universe-agnostic ⊥ is not well-defined for this class.

        Callers should construct a powerset carrier via
        ``build_powerset_heyting_algebra`` and then pick the element
        with the empty subset as the bottom element for that universe.
        """

        raise TypeError("bottom depends on the underlying exclusion universe")

    @classmethod
    def top(cls) -> "PowersetHeytingElement":  # type: ignore[override]
        """Universe-agnostic ⊤ is not well-defined for this class.

        As with ``bottom``, callers should work with concrete carriers
        built via ``build_powerset_heyting_algebra``.
        """

        raise TypeError("top depends on the underlying exclusion universe")

    def meet(self, other: "PowersetHeytingElement") -> "PowersetHeytingElement":
        if self.universe != other.universe:
            raise ValueError("cannot meet elements from different universes")
        return PowersetHeytingElement(universe=self.universe, subset=self.subset & other.subset)

    def join(self, other: "PowersetHeytingElement") -> "PowersetHeytingElement":
        if self.universe != other.universe:
            raise ValueError("cannot join elements from different universes")
        return PowersetHeytingElement(universe=self.universe, subset=self.subset | other.subset)

    def imp(self, other: "PowersetHeytingElement") -> "PowersetHeytingElement":
        if self.universe != other.universe:
            raise ValueError("cannot imply between different universes")
        # a ⇒ b = (U \ a) ∪ b in a powerset Boolean algebra.
        return PowersetHeytingElement(
            universe=self.universe,
            subset=(self.universe - self.subset) | other.subset,
        )


def build_powerset_heyting_algebra(
    void: Relationlessness,
    atom_names: Iterable[str],
) -> FiniteHeytingAlgebra[PowersetHeytingElement]:
    """Build the full finite powerset Heyting algebra from Relationlessness.

    Given a Relationlessness "void" and a finite collection of atom
    names, we introduce exclusion atoms and return the full powerset
    Heyting algebra on that universe as a :class:`FiniteHeytingAlgebra`.
    """

    atoms: tuple[ExclusionAtom, ...] = atoms_from_relationlessness(void, tuple(atom_names))
    universe: frozenset[ExclusionAtom] = frozenset(atoms)
    atom_list: list[ExclusionAtom] = list(universe)

    elements: List[PowersetHeytingElement] = []
    n = len(atom_list)
    for k in range(0, n + 1):
        for combo in combinations(atom_list, k):
            subset = frozenset(combo)
            elements.append(PowersetHeytingElement(universe=universe, subset=subset))

    return FiniteHeytingAlgebra(elements=tuple(elements))


def build_three_chain_heyting_algebra(
    void: Relationlessness,
) -> FiniteHeytingAlgebra[PowersetHeytingElement]:
    """Build a three-element Heyting chain as a powerset subalgebra.

    This mirrors the original ThreeHA carrier as the subalgebra
    {⊥, {α}, {α, β}} of the powerset Heyting algebra on a two-atom
    exclusion universe derived from Relationlessness.
    """

    atoms: tuple[ExclusionAtom, ...] = atoms_from_relationlessness(void, ["•", "◦"])
    universe: frozenset[ExclusionAtom] = frozenset(atoms)
    alpha = atoms[0]

    bottom = PowersetHeytingElement(universe=universe, subset=frozenset())
    mid = PowersetHeytingElement(universe=universe, subset=frozenset({alpha}))
    top = PowersetHeytingElement(universe=universe, subset=universe)

    return FiniteHeytingAlgebra(elements=(bottom, mid, top))


__all__ = [
    "FiniteHeytingAlgebra",
    "close_under_heyting_ops",
    "PowersetHeytingElement",
    "build_powerset_heyting_algebra",
    "build_three_chain_heyting_algebra",
]
